def extract(text, name):
    tokens = r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|/\*[\s\S]*?\*/|//[^\n]*'
    masked = re.sub(tokens, lambda m: ' ' * len(m.group()), text)
    pattern = (r'(?:static\s+)?(?:inline\s+)?(?:void|int|bool)\s+\b'
               + re.escape(name) + r'\s*\([^;{}]*\)\s*\{')
    matches = list(re.finditer(pattern, masked))
    if len(matches) != 1:
        raise ValueError('Missing/ambiguous SPI queue function: ' + name)
    start = matches[0].start()
    opening = text.index('{', start)
    depth = 0
    for token in re.finditer(tokens + r'|[{}]', text[opening:]):
        if token.group() == '{':
            depth += 1
        elif token.group() == '}':
            depth -= 1
            if not depth:
                return text[start:opening + token.end()]
    raise ValueError('Unterminated SPI queue function: ' + name)


def actual_functions(texts):
    out = {}
    for key, names in FUNCTIONS.items():
        for name in names:
            text = texts[key]
            if key == 'core' and name == '__spi_unmap_msg':
                text = text[text.index('#ifdef CONFIG_HAS_DMA'):text.index('#else /* !CONFIG_HAS_DMA */')]
            if key == 'pm_header' and name == 'pm_runtime_put_noidle':
                text = text[text.index('#ifdef CONFIG_PM'):text.index('#else')]
            out[name] = {'source_key': key, 'body': extract(text, name)}
    return out


def production_fragments(texts):
    text = texts['pm_header']
    return text[text.index('/* Runtime PM flag argument bits */'):
                text.index('#ifdef CONFIG_PM')]


