def generate_source(texts, fixture_root=None, owner_uid=0, baseline=False):
    if set(texts) != set(SOURCE_PATHS):
        raise ValueError('Exact SPI queue source manifest required')
    if type(owner_uid) is not int or type(baseline) is not bool:
        raise ValueError('Typed generation arguments required')
    functions = actual_functions(texts)
    bodies = {n: r['body'] for n, r in functions.items()}
    fragments = production_fragments(texts)
    if baseline:
        if set(BASELINE_FUNCTIONS) != set(BASELINE_FUNCTIONS_SHA256):
            raise ValueError('Unpinned SPI queue baseline manifest')
        for name, body in BASELINE_FUNCTIONS.items():
            if hashlib.sha256(body.encode()).hexdigest() != BASELINE_FUNCTIONS_SHA256[name]:
                raise ValueError('Changed literal SPI queue baseline: ' + name)
        if hashlib.sha256(BASELINE_FRAGMENTS.encode()).hexdigest() != BASELINE_FRAGMENTS_SHA256:
            raise ValueError('Changed literal SPI queue PM flags baseline')
        bodies = dict(BASELINE_FUNCTIONS)
        fragments = BASELINE_FRAGMENTS
    return (PREFIX + '\n' + fragments + '\n' + '\n\n'.join(
        bodies[name] for names in FUNCTIONS.values() for name in names if name in bodies) + '\n' + DRIVER)

